    private static final Pattern CONTACT_NUMBER_PATTERN = Pattern.compile(Patterns.CONTACT_NUBMER_PATTERN);

    public ParticipatingMember updateMember(UUID projectId, ParticipatingMember member, boolean isRoleUpdated)
            throws DuplicateEntryException, RequiredFieldsMissingException, NoSuchElementException,
            InvalidInputException, MaxUsersExceededException {

        validateParticipatingMemberForEdit(projectId, member, isRoleUpdated);
        log.info("member update with company: " + member.getCompanyName() + " and role: " + member.getRoleName());
        return save(member);
    }

    public ParticipatingMember addLoggedInUserAsAdmin(UUID projectId, ParticipatingCompany company)
            throws DuplicateEntryException, RequiredFieldsMissingException, NoSuchElementException,
            InvalidInputException, MaxUsersExceededException {
        return addLoggedInUserToProject(projectId, ProjectUserRole.ADMINISTRATOR, company);
    }

    public ParticipatingMember addLoggedInUserToProject(UUID projectId, ProjectUserRole projectUserRole, ParticipatingCompany company)
            throws DuplicateEntryException, RequiredFieldsMissingException, NoSuchElementException,
            InvalidInputException, MaxUsersExceededException {
        ParticipatingMember participatingMember = new ParticipatingMember();

        participatingMember.setUserId(UUID.fromString(authContextProvider.getUserId()));
        participatingMember.setOtdsUserId(UUID.fromString(authContextProvider.getOtdsUserId()));
        participatingMember.setTenantId(UUID.fromString(authContextProvider.getTenantId()));
        participatingMember.setSubscriptionId(UUID.fromString(authContextProvider.getSubscriptionId()));
        participatingMember.setProjectId(projectId);
        participatingMember.setName(authContextProvider.getUserName());
        participatingMember.setEmail(authContextProvider.getUserEmail());
        participatingMember.setContactNumber("");
        participatingMember.setRoleName(projectUserRole.getValue());
        participatingMember.setStatus(UserStatus.ACTIVE.getValue());
        participatingMember.setCompany(company);

        validateParticipatingMemberForAdd(projectId, participatingMember);

        return save(participatingMember);
    }

    //Method is used to for setting up status of a member based on saga configuration
    public List<ParticipatingMember> addMembers(String status, List<ParticipatingMember> members, UUID projectId, UUID subscriptionId,
                                                UUID tenantId, String accessToken)
            throws NoSuchElementException, InvalidInputException, MaxUsersExceededException, ObjectNotFoundException,
            UnauthorizedUserActionException, ActiveUserNotFoundInSubscriptionException, InvalidPatternException, DuplicateEntryException {
        members.forEach(member -> member.setStatus(status));
        return addMembers(members, false, projectId, subscriptionId, tenantId, accessToken);
    }

    public List<ParticipatingMember> addMembers(List<ParticipatingMember> members, boolean includeInvitationPending,
                                                UUID projectId, UUID subscriptionId, UUID tenantId, String accessToken)
            throws NoSuchElementException, InvalidInputException, MaxUsersExceededException, ObjectNotFoundException,
            UnauthorizedUserActionException, ActiveUserNotFoundInSubscriptionException, InvalidPatternException, DuplicateEntryException {
        int count = 0;
        List<ParticipatingMember> users = new ArrayList<>();
        List<String> usersNotInSystem = new ArrayList<>();

        Map<String, User> subscriptionUsersMap = entitlementService.getUsersInSubscriptionGroupedByEmail("", includeInvitationPending,
                true, subscriptionId.toString(), tenantId.toString(), accessToken);
        for (ParticipatingMember member : members) {
            if (!subscriptionUsersMap.containsKey(member.getEmail())) {
                if (!FieldValidation.isValidEmail(member.getEmail())) {
                    throw new InvalidPatternException("email");
                }
                User user;
                log.info("adding user with {} email in the subscription", member.getEmail());
                try {
                    user = entitlementService.addUserToSubscription(member.getEmail(), subscriptionId.toString(),
                            tenantId.toString(), accessToken);
                } catch (RuntimeException e){
                    if ( e.getCause() instanceof WebClientResponseException &&
                            ((WebClientResponseException)e.getCause()).getStatusCode() == HttpStatus.CONFLICT) {
                        log.info("user with {} email in the subscription already exist", member.getEmail());
                        user = entitlementService.getUsersInSubscription(member.getEmail(), true,
                                true, subscriptionId.toString(), tenantId.toString(), accessToken).stream().findFirst().get();
                    } else {
                        throw e;
                    }
                }
                subscriptionUsersMap.put(user.getEmail(), user);
            }
            if (isDuplicateEntry(projectId, member)) {
                if (authContextProvider.isMigrationFlow()) {
                    continue;
                }
                throw new DuplicateEntryException(ParticipatingMember.class.getSimpleName(), member.getEmail());
            }
            validateCoordinatorCount(member, projectId, count, false);
            ParticipatingCompany defaultOrganization = (DEFAULT_ORG_NAME.equals(member.getCompanyName())) ?
                    getDefaultOrganization(projectId, subscriptionId, tenantId) : null;

            ParticipatingCompany company = validateCompanyAndCompanyStatus(member.getCompanyName(), projectId, defaultOrganization);
            validateMember(member, projectId);
            ParticipatingMember user = prepareParticipatingMemberObject(subscriptionUsersMap.get(member.getEmail()),
                    member, company, projectId, subscriptionId, tenantId);
            users.add(user);
            if (!subscriptionUsersMap.containsKey(member.getEmail())) {
                log.error("An active user with email {} doesn't exist in the subscription", member.getEmail());
                usersNotInSystem.add(member.getEmail());
            }
        }

        if (usersNotInSystem.size() > 0) {
            log.error("Could not find active user(s) with name/email {} in current subscription",
                    Arrays.toString(usersNotInSystem.toArray()));
            throw new ActiveUserNotFoundInSubscriptionException(usersNotInSystem.toArray(new String[0]));
        }

        return saveAll(users);
    }

    private ParticipatingMember prepareParticipatingMemberObject(User subscriptionUser, ParticipatingMember member, ParticipatingCompany company,
                                                                 UUID projectId, UUID subscriptionId, UUID tenantId) {

        ParticipatingMember user = findParticipantMember(projectId, UUID.fromString(subscriptionUser.getOtdsUuid()));
        if (user == null) {
            user = new ParticipatingMember();
        }
        user.setUserId(UUID.fromString(subscriptionUser.getUserProfileId()));
        user.setTenantId(tenantId);
        user.setSubscriptionId(subscriptionId);
        user.setContactNumber(subscriptionUser.getPhone());
        user.setEmail(member.getEmail());
        user.setStatus(member.getStatus());
        user.setProjectId(projectId);
        if (StringUtils.isBlank(member.getRoleName())) {
            user.setRoleName(ProjectUserRole.MEMBER.getValue());
        } else {
            user.setRoleName(member.getRoleName());
        }
        user.setOtdsUserId(UUID.fromString(subscriptionUser.getOtdsUuid()));
        user.setProjectId(projectId);
        user.setTitle(member.getTitle());
        user.setName(subscriptionUser.getFirstName() + ' ' + subscriptionUser.getLastName());
        user.setCompany(company);
        return user;
    }

    private void validateMember(ParticipatingMember member, UUID projectId) throws InvalidInputException, UnauthorizedUserActionException {
        //validate role
        if (member.getRoleName() != null && !member.getRoleName().isBlank()
                && ProjectUserRole.getValue(member.getRoleName()) == null) {
            throw new InvalidInputException("Member role");
        }

        if (!authContextProvider.isApplicationAdmin()) {
            ParticipatingMember loggedInUser = findParticipantMember(projectId);
            //Coordinator should not add any user other than member
            if (!ProjectUserRole.MEMBER.getValue().equalsIgnoreCase(member.getRoleName()) && ProjectUserRole.COORDINATOR.getValue().equalsIgnoreCase(loggedInUser.getRoleName())) {
                throw new UnauthorizedUserActionException();
            }

            //Coordinator should not add user other one that belongs to his company
            if (ProjectUserRole.MEMBER.getValue().equalsIgnoreCase(member.getRoleName()) && ProjectUserRole.COORDINATOR.getValue().equalsIgnoreCase(loggedInUser.getRoleName())
                    && !member.getCompanyName().equalsIgnoreCase(loggedInUser.getCompany().getName())) {
                throw new UnauthorizedUserActionException();
            }

            //Only an administrator can add another administrator
            if (ProjectUserRole.ADMINISTRATOR.getValue().equalsIgnoreCase(member.getRoleName()) && !ProjectUserRole.ADMINISTRATOR.getValue().equalsIgnoreCase(loggedInUser.getRoleName())) {
                throw new UnauthorizedUserActionException();
            }
        }

    }

    //Todo Need to get rid of this method once Edit Member Saga is refactored , need to move input validation to user validator and use validate member for validation
    private void validateParticipatingMember(UUID projectId, ParticipatingMember member, boolean isAdd, boolean isRoleUpdated)
            throws RequiredFieldsMissingException, DuplicateEntryException,
            InvalidInputException, MaxUsersExceededException {
        if (member.getCompany() == null || member.getCompany().getId() == null) {
            throw new RequiredFieldsMissingException("company");
        }
        if (member.getContactNumber() != null && !member.getContactNumber().isBlank()) {
            Matcher patternMatcher = CONTACT_NUMBER_PATTERN.matcher(member.getContactNumber());

            if (!patternMatcher.matches()) {
                throw new InvalidInputException("Contact number");
            }
        }

        if (member.getEmail() == null || member.getEmail().isEmpty()) {
            throw new RequiredFieldsMissingException("email");
        }
        if (member.getRoleName() != null && !member.getRoleName().isBlank()
                && ProjectUserRole.getValue(member.getRoleName()) == null) {
            throw new InvalidInputException("Member role");
        }
        if (isRoleUpdated && ProjectUserRole.getValue(member.getRoleName()) == ProjectUserRole.COORDINATOR) {
            int coordinatorCount = activeCoordinatorCount(projectId);
            if (coordinatorCount >= NUMBER_OF_ALLOWED_COORDINATORS) {
                throw new MaxUsersExceededException(NUMBER_OF_ALLOWED_COORDINATORS, ProjectUserRole.COORDINATOR.toString());
            }
        }
        if (isAdd) {
            if (isDuplicateEntry(projectId, member)){
                throw new DuplicateEntryException(ParticipatingMember.class.getSimpleName(), member.getEmail());
            }

            // set company based on Id from request.
            ParticipatingCompany company = companyRepository.findById(member.getCompany().getId()).orElseThrow();
            member.setCompany(company);
        }
    }

    private boolean isDuplicateEntry(UUID projectId, ParticipatingMember member) {
        ExampleMatcher matcher = ExampleMatcher.matching().withIgnoreCase().withIgnoreNullValues();

        ParticipatingMember emailProbe = new ParticipatingMember();
        emailProbe.setProjectId(projectId);
        emailProbe.setEmail(member.getEmail());
        emailProbe.setRoleName(member.getRoleName());
        long emailCount = memberRepository.count(Example.of(emailProbe, matcher));

        return emailCount > 0;
    }

    private void validateParticipatingMemberForAdd(UUID projectId, ParticipatingMember member)
            throws RequiredFieldsMissingException, DuplicateEntryException,
            InvalidInputException, MaxUsersExceededException {
        validateParticipatingMember(projectId, member, true, true);
    }

    private void validateParticipatingMemberForEdit(UUID projectId, ParticipatingMember member, boolean isRoleUpdated)
