    private void validateCoordinatorCount(ParticipatingMember member, UUID projectId, int count, boolean isRoleUpdate) throws MaxUsersExceededException {
        int coordinatorCountFromDB = activeCoordinatorCount(projectId);
        if (isRoleUpdate) {
            if (coordinatorCountFromDB >= NUMBER_OF_ALLOWED_COORDINATORS) {
                throw new MaxUsersExceededException(NUMBER_OF_ALLOWED_COORDINATORS, ProjectUserRole.COORDINATOR.toString());
            }
        } else {
            if (ProjectUserRole.getValue(member.getRoleName()) == ProjectUserRole.COORDINATOR) {
                count++;
            }

            if (coordinatorCountFromDB + count > NUMBER_OF_ALLOWED_COORDINATORS) {
                throw new MaxUsersExceededException(NUMBER_OF_ALLOWED_COORDINATORS, ProjectUserRole.COORDINATOR.toString());
            }
        }

    }

    public ParticipatingCompany validateCompanyAndCompanyStatus(String companyName, UUID projectId, ParticipatingCompany defaultOrganization) throws ObjectNotFoundException, InvalidInputException {
        ParticipatingCompany company = companyRepository.findByNameAndProjectId(companyName, projectId);
        //Validate company exist in current project
        //Save the Default Organization provided from se connector apis input if it doesnot exist
        if (company == null) {
            if (!DEFAULT_ORG_NAME.equals(companyName)) {
                throw new ObjectNotFoundException("Company", companyName);
            }
            company = companyRepository.save(defaultOrganization);
        }

        //validate that company is in active state
        if (!company.getStatus().equals(OrganizationStatus.ACTIVE.getValue())) {
            throw new InvalidInputException("Inactive Company - Company provided");
        }
        return company;
    }

    public List<ParticipatingMember> getParticipatingMembersByProjectId(UUID projectId) {
