    }

    public boolean isContractMemberRoleInAllowedRoles(UUID userId, UUID contractId, List<String> roleNames) throws ObjectNotFoundException {
        ContractMember contractMember = findContractMember(userId, contractId);
        if (contractMember != null) {
            return containsRole(roleNames, contractMember.getRoleName());

        }
        return false;
    }

    private boolean containsRole(List<String> allowedRoles, List<String> actualRoles) {
        return actualRoles.stream().anyMatch(allowedRoles::contains);
    }

    /**
     * Get contract members with optional pagination
     *
     * @param filter Filter criteria (required)
     * @return List of contract members (all results if pageRequest is null)
     */
    public List<ContractMember> getMembers(FilterContractMemberInput filter) throws RequiredFieldsMissingException, ObjectNotFoundException {
        return getMembers(filter, null);
    }

    /**
     * Get contract members with optional pagination
     *
     * @param filter Filter criteria (required)
     * @param pageRequest Pagination parameters (optional - if null, returns all results)
     * @return List of contract members
     */
    public List<ContractMember> getMembers(FilterContractMemberInput filter, PageRequestInput pageRequest) throws RequiredFieldsMissingException, ObjectNotFoundException {
        validateRequest(filter);

        // Form the query with all required parameters
        Query contractMembersQuery = generateContractMembersQuery(filter, CONTRACT_MEMBERS_BASE_QUERY, true);

        // Apply pagination if provided (otherwise returns all results)
        if (pageRequest != null) {
            pageRequest = PageRequestInput.getEffectivePageRequestInput(pageRequest);
            int pageNumber = pageRequest.getPage();
            int pageSize = pageRequest.getSize();
            // Pagination uses 1-based indexing for pages
            contractMembersQuery.setFirstResult((pageNumber <= 0 ? 0 : pageNumber - 1) * pageSize);
            contractMembersQuery.setMaxResults(pageSize);
        }

        List<ContractMember> contractMembers = getContractMembers(contractMembersQuery);
        return postProcess(contractMembers, filter);
    }

    /**
     * Get the count of contract members for a given contract, optionally filtered by search term.
     *
     * @param contractId the contract id
     * @param search optional search term to filter by userName, userEmail or companyName
     * @return count of contract members
     */
    public long getMembersCount(String contractId, String search) throws ObjectNotFoundException {
        isContractExist(UUID.fromString(contractId));
        if (search == null || search.isBlank()) {
            return contractMemberRepository.countByContractId(UUID.fromString(contractId));
        }
        FilterContractMemberInput filter = new FilterContractMemberInput();
        FilterIdInput contractIdFilter = new FilterIdInput();
        contractIdFilter.setEq(contractId);
        filter.setContractId(contractIdFilter);
        filter.setSearch(search);
        Query countQuery = generateContractMembersQuery(filter, CONTRACT_MEMBERS_COUNT_QUERY, false);
        return (long) countQuery.getSingleResult();
    }

    private void validateRequest(FilterContractMemberInput filter) throws RequiredFieldsMissingException, ObjectNotFoundException {
        if (filter.getContractId() == null) {
            throw new RequiredFieldsMissingException(CONTRACT_ID);
        }
        Contract contract = contractService.getContractById(UUID.fromString(filter.getContractId().getEq()));
        ParticipatingMember projectMember = participatingMemberService.getProjectMembership(UUID.fromString(authContextProvider.getOtdsUserId()),
                contract.getProjectId(), UUID.fromString(authContextProvider.getSubscriptionId()));
        if (!authContextProvider.isApplicationAdmin() && !projectMember.getRoleName().equals(ROLE_ADMINISTRATOR)) {
            // First validate the current user is member of the provided contract.
            ContractMember contractMember = contractMemberRepository.findByUserIdAndContractId(
                    UUID.fromString(authContextProvider.getOtdsUserId()),
                    UUID.fromString(filter.getContractId().getEq()));
            if (contractMember == null) {
                throw new UserNotAuthorizedForContractException();
            }
        }
    }

    private List<ContractMember> postProcess(List<ContractMember> contractMembers, FilterContractMemberInput filter) {
        if (filter.isFetchLastLoginInfo()) {
            String subscriptionId = authContextProvider.getSubscriptionId();
            String tenantId = authContextProvider.getTenantId();
            String accessToken = authContextProvider.getAccessToken();
            Map<String, User> etsUserMap = new HashMap<>();
            for (ContractMember member : contractMembers) {
                String email = member.getUserEmail();
                if (StringUtils.isBlank(email) || etsUserMap.containsKey(email)) {
                    continue;
                }
                User etsUser = findSubscriptionUserByEmail(email, subscriptionId, tenantId, accessToken);
                if (etsUser != null) {
                    etsUserMap.put(email, etsUser);
                }
            }
            // Filter out users who are no longer part of the subscription
            contractMembers = contractMembers.stream()
                .filter(member -> etsUserMap.containsKey(member.getUserEmail()))
                .collect(Collectors.toList());

            // Set last login info for remaining members
            contractMembers.forEach(member -> {
                User etsUser = etsUserMap.get(member.getUserEmail());
                Date lastLogin = etsUser.getLastLogin();
                if (lastLogin == null) {
                    member.setLastLogin(etsUser.getStatus());
                } else {
                    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
                    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
                    member.setLastLogin(sdf.format(lastLogin));
                }
                if (member.getUserName().equalsIgnoreCase(Constants.INVALID_NAME)) {
                    member.setUserName(etsUser.getFirstName() + " " + etsUser.getLastName());
                }
            });
        }
        return contractMembers;
    }

    @NotNull
    private Query generateContractMembersQuery(FilterContractMemberInput filter, String baseQueryStr, boolean addOrderBy) {

        StringBuilder baseQuery = new StringBuilder().append(baseQueryStr);

        Set<String> paramNames = new HashSet<>();

        if (filter.getSearch() != null && !filter.getSearch().isBlank()) {
            baseQuery.append(" and (lower(pm.name) like :search or lower(pm.email) like :search or lower(pm.company.name) like :search)");
            paramNames.add(SEARCH);
        }

        if (filter.getRoleName() != null) {
            baseQuery.append(" and cm.roleName in (:roleNames)");
            paramNames.add(ROLE_NAMES);
        }
        if (addOrderBy) {
            //Always order by the role name.
            baseQuery.append(" order by cm.roleName ASC, cm.contract.name ASC");
        }
        log.info("Query: " + baseQuery);
        //Create query and then set parameters.
        Query contractMembersQuery = entityManager.createQuery(baseQuery.toString());
        setQueryParams(filter, paramNames, contractMembersQuery);
        return contractMembersQuery;
    }

    private void setQueryParams(FilterContractMemberInput filter, Set<String> paramNames, Query contractMembersQuery) {
        contractMembersQuery.setParameter(SUBSCRIPTION_ID, UUID.fromString(authContextProvider.getSubscriptionId()));
        contractMembersQuery.setParameter(CONTRACT_ID, UUID.fromString(filter.getContractId().getEq()));
        paramNames.forEach(paramName -> {
            switch (paramName) {
                case ROLE_NAMES:
                    contractMembersQuery.setParameter(ROLE_NAMES, Arrays.asList(getRoles(filter)));
                    break;
                case SEARCH:
                    contractMembersQuery.setParameter(SEARCH, '%' + filter.getSearch().toLowerCase() + '%');
                    break;
            }
        });
    }

    private List<String> getRoles(FilterContractMemberInput filter) {
        List<String> roleNames = new ArrayList<>();
        for (FilterStringInput filterIn : filter.getRoleName()) {
            roleNames.add(filterIn.getEq());
        }
        return roleNames;
    }

    private List<ContractMember> getContractMembers(Query contractMembersQuery) {
        List<Object[]> results = contractMembersQuery.getResultList();
        List<ContractMember> contractMembers = new ArrayList<>();
        // Parallel stream is avoided here because ArrayList is not thread-safe.
        // Concurrent modification from multiple threads may lead to race conditions
        // and inconsistent results. If parallel processing is required,
        // use a thread-safe collection (e.g., CopyOnWriteArrayList) or
        // collect results using stream collectors instead of mutating shared state.
        results.forEach(result -> {
            ContractMember contractMember = new ContractMember();
            contractMember.setId((UUID) result[0]);
            contractMember.setUserId((UUID) result[1]);
            contractMember.setRoleName((List<String>) result[2]);
            Contract contract = new Contract();
            contract.setId((UUID) result[3]);
            contractMember.setContract(contract);
            contractMember.setUserName(result[4].toString());
            contractMember.setUserEmail(result[5].toString());
            contractMember.setCompanyId((UUID) result[6]);
            contractMember.setCompanyName(result[7].toString());
            contractMembers.add(contractMember);
        });
        return contractMembers;
    }

    @Override
    public IContractMember getLoggedInUserMembership(UUID contractId) {
        if (authContextProvider == null) {
            throw new RuntimeException("Could not fetch authentication context");
        }

        // for service account, there will be no membership details so return null
        if (authContextProvider.isApplicationAdmin()) return null;
        return getContractMembership(contractId,
                UUID.fromString(authContextProvider.getOtdsUserId()));
    }

    @SneakyThrows
    @Override
    public IContractMember getContractMembership(UUID contractId, UUID userId) {
        FilterContractMemberInput filter = generateContractMemberFilter(contractId);
        return getMembers(filter).stream().findFirst().orElse(null);
    }

    @SneakyThrows
    @Override
    public Boolean isContractInUserSubscription(UUID contractId) {
        List<ContractMember> contractMembers = contractMemberRepository.findByContract_IdAndSubscriptionId(contractId, UUID.fromString(authContextProvider.getSubscriptionId()));
        return contractMembers != null && !contractMembers.isEmpty();
    }

    @NotNull
    private FilterContractMemberInput generateContractMemberFilter(UUID contractId) {
        FilterContractMemberInput filter = new FilterContractMemberInput();
        FilterIdInput filterContractId = new FilterIdInput();
        filterContractId.setEq(contractId.toString());
        filter.setContractId(filterContractId);
        return filter;
    }

    @Override
    public Boolean isUserActiveMemberOfProject(IContractMember contractMember) {
        Contract contract = contractRepository.findById(contractMember.getContractId()).orElse(null);
        if (null == contract) {
            log.warn("contract not found with id " + contractMember.getContractId());
            return false;
        }
        return projectMembershipCheckService.isUserActiveMember(contract.getProjectId().toString());
    }

    public ContractMember addLoggedInUserAsCoordinator(UUID contractId)
            throws InvalidInputException, RequiredFieldsMissingException, ObjectNotFoundException, DuplicateEntryException,
            UnauthorizedUserActionException, ActiveUserNotFoundInSubscriptionException, InvalidPatternException, MaxUsersExceededException {

        //get contract for given id
        Contract contract = contractService.getContractById(contractId);

        //populate contract member
        ContractMember contractMember = ContractMember.builder()
                .roleName(List.of(Roles.Contract.Coordinator.name()))
                .userId(UUID.fromString(authContextProvider.getOtdsUserId()))
                .userEmail(authContextProvider.getUserEmail())
                .subscriptionId(UUID.fromString(authContextProvider.getSubscriptionId()))
                .tenantId(UUID.fromString(authContextProvider.getTenantId()))
                .companyName(contract.getOwner())
                .contract(contract)
                .build();

        //validate all required fields are set and uniqueness
        validateMemberInput(contractMember);

        //fetch list of emails of the project participant members
        List<String> existingParticipatingMembers = participatingMemberService.getParticipatingMembersByProjectId(contract.getProjectId())
                .stream().map(ParticipatingMember::getEmail)
                .collect(Collectors.toList());

        //validate if the current user is a participating member. If not, add.
        if (!existingParticipatingMembers.contains(contractMember.getUserEmail())) {
            ParticipatingMember participatingMember = buildParticipatingMemberObject(contractMember, contract.getProjectId());
            	//add contract members as participating member who were not part of the respective project
                participatingMemberService.addMembers(List.of(participatingMember), true, contract.getProjectId(),
                        UUID.fromString(authContextProvider.getSubscriptionId()), UUID.fromString(authContextProvider.getTenantId()),
                        authContextProvider.getAccessToken());
        }

        //Note: since we are adding an already loggedIn user, he is already part of subscription, so no need for the etsuser check
        // and since the auth check already verifies that he is part of the project, no need to add to participating member list

        //save the contract member
        return save(contractMember);
    }
    public List<ContractMember> addMembers(UUID contractId, List<ContractMember> contractMembers)
    		throws RequiredFieldsMissingException, DuplicateEntryException, InvalidInputException,
    		MaxUsersExceededException, ObjectNotFoundException, NoSuchElementException, UnauthorizedUserActionException,
    		InvalidPatternException, ActiveUserNotFoundInSubscriptionException {
    	List<ContractMember> newContractMembers = new ArrayList<>();
        HashMap<UUID, String> userDetails = new HashMap<>();
    	// get contract for given id
    	Contract contract = contractService.getContractById(contractId);
        // retrieve subscription users details from ETS
    	String subscriptionId = authContextProvider.getSubscriptionId();
    	String tenantId = authContextProvider.getTenantId();
    	String accessToken = authContextProvider.getAccessToken();
        Map<String, User> etsUserMap = entitlementService.getUsersInSubscriptionGroupedByEmail("", true, true, subscriptionId, tenantId, accessToken);

        // fetch list of emails of the project participant members
    	List<String> existingParticipatingMembers = participatingMemberService
    			.getParticipatingMembersByProjectId(contract.getProjectId()).stream().map(ParticipatingMember::getEmail)
    			.collect(Collectors.toList());

    	// validate and update the pojos with appropriate info
    	List<ParticipatingMember> participatingMembersToBeAdded = new ArrayList<>();
    	for (ContractMember member : contractMembers) {
    		// check if the user is part of subscription. Else add the user in the subscription.
            if (etsUserMap.containsKey(member.getUserEmail())) {
                member.setUserId(UUID.fromString(etsUserMap.get(member.getUserEmail()).getOtdsUuid()));
    		} else {
    			if (!FieldValidation.isValidEmail(member.getUserEmail())) {
    				throw new InvalidPatternException("email");
    			}
    			log.info("adding user with {} email in the subscription", member.getUserEmail());
                User user;
                try {
                    user = entitlementService.addUserToSubscription(member.getUserEmail(), subscriptionId,
                            tenantId, accessToken);
                } catch (RuntimeException e){
                    if ( e.getCause() instanceof WebClientResponseException &&
                            ((WebClientResponseException)e.getCause()).getStatusCode() == HttpStatus.CONFLICT) {
                        log.info("user with {} email in the subscription already exist", member.getUserEmail());
                        user = entitlementService.getUsersInSubscription(member.getUserEmail(), true,
                                true, subscriptionId, tenantId, accessToken).stream().findFirst().get();
                    } else {
                        throw e;
                    }
                }
    			member.setUserId(UUID.fromString(user.getOtdsUuid()));
    		}

            member.setTenantId(UUID.fromString(authContextProvider.getTenantId()));
            member.setSubscriptionId(UUID.fromString(authContextProvider.getSubscriptionId()));

    		// create a list of non-existing participating members
    		if (!existingParticipatingMembers.contains(member.getUserEmail())) {
    			participatingMembersToBeAdded.add(buildParticipatingMemberObject(member, contract.getProjectId()));
    		}

    		member.setContract(contract);
            userDetails.put(member.getUserId(), member.getUserEmail());
            // validate all required fields are set and uniqueness
    		if(validateMemberInput(member)) {
                try{
                    // Updating role of the existing contract member
                    ContractMember existingContractMember = findContractMember(member.getUserId(), member.getContract());
                    for(String role : member.getRoleName()) {
                        if(!existingContractMember.getRoleName().contains(role)) {
                            existingContractMember.getRoleName().add(role);
                        }
                    }
                    newContractMembers.add(existingContractMember);
                }
                catch (ObjectNotFoundException e) {
                    newContractMembers.add(member);
                }
    		}
    	}

    	if (participatingMembersToBeAdded.size() > 0) {
    		// add contract members as participating member who were not part of the
    		// respective project
    		participatingMemberService.addMembers(participatingMembersToBeAdded, true, contract.getProjectId(),
    				UUID.fromString(subscriptionId), UUID.fromString(tenantId), accessToken);
    	}

        // save the contract members
        List<ContractMember> savedContractMembers;
        try {
            savedContractMembers = saveAll(newContractMembers);
        } catch (DataIntegrityViolationException integrityViolationException) {
            log.info("DataIntegrityViolationException while adding contract members, could be due to concurrency, hence retrying... "+integrityViolationException.getMessage());
            List<ContractMember> newContractMembersRetry = new ArrayList<>();
            for (ContractMember member : newContractMembers) {
                try {
                    // Updating role of the existing contract member
                    ContractMember existingContractMember = findContractMember(member.getUserId(), member.getContract());
                    for (String role : member.getRoleName()) {
                        if (!existingContractMember.getRoleName().contains(role)) {
                            existingContractMember.getRoleName().add(role);
                        }
                    }
                    newContractMembersRetry.add(existingContractMember);
                } catch (ObjectNotFoundException exception) {
                    newContractMembersRetry.add(member);
                }
            }
            savedContractMembers = saveAll(newContractMembersRetry);
        }

        //Setting email for the existing saved contract member
        for(ContractMember contractMember : savedContractMembers) {
            contractMember.setUserEmail(userDetails.get(contractMember.getUserId()));
        }
        return savedContractMembers;
    }

    private User findSubscriptionUserByEmail(String email, String subscriptionId, String tenantId, String accessToken) {
        if (StringUtils.isBlank(email)) {
            return null;
        }
        return entitlementService.getUsersInSubscription(email, true, true, true, subscriptionId, tenantId, accessToken)
                .stream()
                .filter(user -> user.getEmail() != null && user.getEmail().equalsIgnoreCase(email))
                .findFirst()
                .orElse(null);
    }

    public List<ContractMember> updateContractMembers(UUID contractId, List<ContractMember> contractMembers)
            throws  InvalidInputException, ObjectNotFoundException, NoSuchElementException {
        Contract contract = contractService.getContractById(contractId);
        List<ContractMember> updatedContractMembers = null;
        for(ContractMember member :contractMembers) {
            updateParticipatingMember(contract, member);
            updatedContractMembers = updateContractMember(contract, member);
        }
        return updatedContractMembers;
    }

    public void updateParticipatingMember(Contract contract, ContractMember member)
            throws  InvalidInputException, ObjectNotFoundException, NoSuchElementException {
        String subscriptionId = authContextProvider.getSubscriptionId();
        String tenantId = authContextProvider.getTenantId();
        List<ParticipatingMember> users = new ArrayList<>();
        ParticipatingMember participatingMember = participatingMemberService.findByOtdsUserIdAndProjectId(member.getUserId(), contract.getProjectId());
        //Updating the organization
        if (participatingMember != null && member.getCompanyName() != null) {
            ParticipatingCompany defaultOrganization = (DEFAULT_ORG_NAME.equals(participatingMember.getCompanyName())) ?
                    participatingMemberService.getDefaultOrganization(contract.getProjectId(), UUID.fromString(subscriptionId), UUID.fromString(tenantId)) : null;
            ParticipatingCompany company = participatingMemberService.validateCompanyAndCompanyStatus(member.getCompanyName(), contract.getProjectId(), defaultOrganization);
            participatingMember.setCompany(company);
            participatingMember.setCompanyName(member.getCompanyName());
            users.add(participatingMember);
        }
        participatingMemberService.saveAll(users);
    }

    public List<ContractMember> updateContractMember(Contract contract, ContractMember member)
            throws ObjectNotFoundException, NoSuchElementException {
        ContractMember contractMember = findContractMember(member.getUserId(), contract.getId());
        if (member.getCompanyName() != null) {
            contractMember.setCompanyName(member.getCompanyName());
        }
        //updating the contract member roles
        List<String> roles = member.getRoleName();
        if (roles != null) {
            contractMember.setRoleName(roles);
        }
        return saveAll(List.of(contractMember));
    }

    private ParticipatingMember buildParticipatingMemberObject(ContractMember contractMember, UUID projectId)
            throws NoSuchElementException {
        ParticipatingMember user = new ParticipatingMember();
        ParticipatingCompany org = organizationService.getCompany(contractMember.getCompanyName(), projectId);
        if(org == null){
            user.setCompanyName(DEFAULT_ORG_NAME);
        }
        else {
            user.setCompany(org);
            user.setCompanyName(contractMember.getCompanyName());
        }
        user.setStatus(UserStatus.ACTIVE.getValue());
        user.setRoleName(ProjectUserRole.MEMBER.getValue());
        user.setEmail(contractMember.getUserEmail());
        return user;
    }

    public void validateAndDeleteContractMembers(UUID contractId, List<ContractMember> contractMembers)
            throws ObjectNotFoundException, NoSuchElementException, RequiredFieldsMissingException {
        Contract contract = contractService.getContractById(contractId);
        for(ContractMember member : contractMembers) {
            ContractMember contractMember = findContractMember(member.getUserId(), contract.getId());
            if (contractMember != null) {
                contractMemberDeleteService.deleteContractMembers(List.of(contractMember));
            }
        }
    }

}
