file_path='issues-service/src/main/java/com/opentext/solutions/services/issues/gql/client/area/service/GqlBasedProjectService.java' content='package com.opentext.solutions.services.issues.gql.client.area.service;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

import tools.jackson.core.type.TypeReference;
import com.opentext.solutions.common.gql.client.service.impl.GraphQLClientService;
import com.opentext.solutions.services.issues.gql.client.area.constants.GQL_Constants;
import com.opentext.solutions.services.issues.gql.client.area.model.GQL_Contract;
import com.opentext.solutions.services.issues.gql.client.area.model.GQL_ContractMembers;
import com.opentext.solutions.services.issues.gql.client.area.model.GQL_ProjectMembers;
import com.opentext.solutions.services.issues.rest.model.FilterContractMemberInput;
import com.opentext.solutions.services.issues.rest.model.FilterIdInput;
import com.opentext.solutions.services.issues.rest.model.FilterParticipantMemberInput;

import lombok.RequiredArgsConstructor;

import static com.opentext.solutions.services.issues.gql.client.area.constants.GQL_Constants.*;

@Service
@RequiredArgsConstructor
public class GqlBasedProjectService {

	@Autowired
	private GraphQLClientService graphQLClientService;

	public List<GQL_ContractMembers> getContractMembers(FilterContractMemberInput filterContractMemberInput) {
		Map variableMap = new HashMap<>();
		variableMap.put(FILTER_VARIABLE_NAME, filterContractMemberInput);
		String variables = graphQLClientService.getVariablesString(variableMap);

		return graphQLClientService.triggerGraphQLQuery(
			GQL_Constants.GET_CONTRACT_MEMBERS_QUERY, 
			variables, 
			GQL_Constants.GET_CONTRACT_MEMBERS_QUERY_NAME, 
			new TypeReference<List<GQL_ContractMembers>>() {
			}, 
			graphQLClientService.getServiceUrls().getProjectsApiUrl()
		);
	}

    public GQL_ContractMembers getContractMember(String contractId, String userId) {
        Map variableMap = new HashMap<>();
        variableMap.put(CONTRACT_ID_VARIABLE_NAME, contractId);
        variableMap.put(USER_ID_VARIABLE_NAME, userId);
        String variables = graphQLClientService.getVariablesString(variableMap);

        return graphQLClientService.triggerGraphQLQuery(
                GQL_Constants.GET_CONTRACT_MEMBER_QUERY,
                variables,
                GQL_Constants.GET_CONTRACT_MEMBER_QUERY_NAME,
                new TypeReference<GQL_ContractMembers>() {
                },
                graphQLClientService.getServiceUrls().getProjectsApiUrl()
        );
    }

    public GQL_ProjectMembers getProjectMember(String projectId, String userId) {
        Map variableMap = new HashMap<>();
        variableMap.put(PROJECT_ID_VARIABLE_NAME, projectId);
        variableMap.put(USER_ID_VARIABLE_NAME, userId);
        String variables = graphQLClientService.getVariablesString(variableMap);

        return graphQLClientService.triggerGraphQLQuery(
                GQL_Constants.GET_PROJECT_MEMBER_QUERY,
                variables,
                GQL_Constants.GET_PROJECT_MEMBER_QUERY_NAME,
                new TypeReference<GQL_ProjectMembers>() {
                },
                graphQLClientService.getServiceUrls().getProjectsApiUrl()
        );
    }

	public GQL_Contract getContract(String contractId, Boolean includeSettings) {
		Map variableMap = new HashMap<>();
		variableMap.put(CONTRACT_ID_VARIABLE_NAME, contractId);
		variableMap.put(INCLUDE_SETTINGS_VARIABLE_NAME, includeSettings);
		String variables = graphQLClientService.getVariablesString(variableMap);

		return graphQLClientService.triggerGraphQLQuery(
				GQL_Constants.GET_CONTRACT_QUERY,
				variables,
				GQL_Constants.GET_CONTRACT_QUERY_NAME,
				new TypeReference<GQL_Contract>() {
				},
				graphQLClientService.getServiceUrls().getProjectsApiUrl()
		);
	}

	public List<GQL_ProjectMembers> getProjectMembers(FilterParticipantMemberInput filterParticipantMemberInput) {
		Map variableMap = new HashMap<>();
		variableMap.put(FILTER_VARIABLE_NAME, filterParticipantMemberInput);
		String variables = graphQLClientService.getVariablesString(variableMap);

		return graphQLClientService.triggerGraphQLQuery(
			GQL_Constants.GET_PROJECT_MEMBERS_QUERY, 
			variables, 
			GQL_Constants.GET_MEMBERS_QUERY_NAME, 
			new TypeReference<List<GQL_ProjectMembers>>() {
			}, 
			graphQLClientService.getServiceUrls().getProjectsApiUrl()
		);
	}
}
