file_path='xchange-ui/src/jato/services/members/jmembers.service.ts' content="import { Injectable } from '@angular/core';
import { Observable, map } from 'rxjs';
import { URIKeyConstant } from 'src/app/constants/uri-key-constant';
import { GraphqlService } from 'src/app/modules/shared/services/graphql.service';
import { ProjectMember } from 'src/app/modules/shared/models/project';
import { Apiurl } from 'src/app/utils/apiurl';


@Injectable({
  providedIn: 'root'
})
export class JMembersService {
  constructor(
    private gqlService: GraphqlService,
    private apiUrl: Apiurl
  ) {}

  /**
   * Gets the count of members for a specific contract
   * @param contractId - The ID of the contract
   * @returns Observable with the member count
   */
  getContractMembersCount(contractId: string): Observable<number> {
    return this.gqlService
      .graphql(
        this.apiUrl.getSourceURL(URIKeyConstant.PROJECTS),
        `query GetContractMembersCount($contractId: String!) {
          contractMembersCount(contractId: $contractId)
        }`,
        { contractId }
      )
      .pipe(
        map((result: any) => {
          const count = result?.data ?? 0;
          return count;
        })
      );
  }

  /**
   * Checks if a user is a member of a project and returns their organization.
   * @param projectId - The ID of the project.
   * @param userId - The ID of the user.
   * @returns Observable with project member details or null.
   */
  checkProjectMembership(projectId: string, userId: string): Observable<ProjectMember | null> {
    return this.gqlService
      .graphql(
        this.apiUrl.getSourceURL(URIKeyConstant.PROJECTS),
        `query CheckProjectMembership($projectId: String!, $userId: String!) {
          checkProjectMembership(projectId: $projectId, userId: $userId) {
            organizationName
          }
        }`,
        { projectId, userId }
      )
      .pipe(
        map((response: any) => {
          return response?.data?.checkProjectMembership ?? null;
        })
      );
  }
}
