/**
 * Query Resolver for project service.
 */
@RequiredArgsConstructor
@Controller
@Slf4j
public class Query {

    private final ProjectService projectService;
    private final RoleService roleService;
    private final StageService stageService;
    private final CountResolver countResolver;
    private final ContractService contractService;
    private final ContractMemberService contractMemberService;
    private final SettingsService settingsService;
    private final UserPreferencesService userPreferencesService;

    @Autowired
    private final ParticipantsService participantsService;

    @Autowired
    private final ParticipatingMemberService memberService;

    @Autowired
    private final ParticipatingCompanyService companyService;

    @Autowired
    private final Map<String, IValidationService> validationServiceMap;

    @Autowired
    private final ProjectValidationService projectValidationService;

    /**
     * Returns all projects.
     *
     * @return projects
     */
    @ExcludeMembershipCheck //excluding membership check validation as it is done at table level
    @QueryMapping
    public List<Project> projects(@Argument FilterProjectInput filter, @Argument PageRequestInput pageRequest) {
        //Note: no need to validate anything here as the query itself returns only those projects in which user is a member of.
        return projectService.getProjects(filter == null ? new FilterProjectInput() : filter, pageRequest);
    }

