    /*
     * doesn't need projectId as argument as per memcheck aspect
     * checks are done from auth context in db level
     */
    @ExcludeMembershipCheck
    @QueryMapping
    public CountsPerProject countsPerProject() {
    	return countResolver.countsPerProject();
    }

    /**
     * Returns a list of members
     *
     * @param filter a filter object for filtering how the members should be fetched
     * @return
     */
    @QueryMapping
    public List<ParticipatingMember> members(@Argument FilterParticipantMemberInput filter) {
        return participantsService.getMembers(filter);
    }

    /**
     * Returns a list of companies/organizations with in subscription if no project id exists in request
     *
     * @param filter a filter object for filtering how the companies should be fetched
     * @return
     */
    @ExcludeMembershipCheck
    @QueryMapping
    public List<ParticipatingCompany> organizations(@Argument FilterParticipantCompanyInput filter, @Argument OrderByInput orderBy) {
        return companyService.getCompanies(filter, orderBy);
    }


    /**
     * Returns all Contracts.
     *
     * @return contracts
     */
    @ExcludeMembershipCheck //excluding membership check validation as it is done during query
    @QueryMapping
    public List<Contract> contracts(@Argument FilterContractInput filter, @Argument PageRequestInput pageRequest) {
        return contractService.getContracts(filter, pageRequest);
    }

    /**
     * Returns contract for the given contract Id.
     *
     * @param contractId
     * @return
     * @throws ObjectNotFoundException
     */
    @ExcludeMembershipCheck //excluding project membership check validation as we are doing contract membership validation.
    @CheckContractMembership
    @QueryMapping
    public Contract contract(@Argument String contractId, @Argument Boolean includeSettings) throws ObjectNotFoundException {
        return contractService.getContractById(UUID.fromString(contractId), includeSettings);
    }

    /**
     * Returns a project Id using legacy Id
     * @param legacyId
     * @return
     */
    @ExcludeMembershipCheck
    @QueryMapping
    public Contract legacyContract(@Argument String legacyId) throws ObjectNotFoundException {
        return contractService.getContractByLegacyId(legacyId);
    }

    /**
     * Returns a list of contract members with optional pagination
     *
     * @param filter a filter object for filtering how the members should be fetched
     * @param pageRequest pagination parameters (optional - if null, returns all results)
     * @return list of contract members
     */
    @QueryMapping
