file_path='se-connector-apis/src/main/java/com/opentext/solutions/services/xchange/service/MemberServiceConnector.java' content='package com.opentext.solutions.services.xchange.service;

import tools.jackson.core.type.TypeReference;
import com.opentext.solutions.common.auth.client.context.AuthContextProvider;
import com.opentext.solutions.common.gql.client.service.impl.GraphQLClientService;
import com.opentext.solutions.services.generated.graphql.types.*;
import com.opentext.solutions.services.xchange.constants.ErrorCode;
import com.opentext.solutions.services.xchange.constants.ErrorMessages;
import com.opentext.solutions.services.xchange.constants.MembersGraphQLConstants;
import com.opentext.solutions.services.xchange.model.AddContractMemberDto;
import com.opentext.solutions.services.xchangev2.exceptionhandler.ForbiddenException;
import com.opentext.solutions.services.xchange.model.AddDeliverableListMemberDto;
import com.opentext.solutions.services.xchange.model.AddDeliverableMemberDto;
import com.opentext.solutions.services.xchange.model.AddProjectMemberDto;
import com.opentext.solutions.services.xchange.utils.RoleNameUtils;
import com.opentext.solutions.services.xchange.utils.GraphQLUtil;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

import static com.opentext.solutions.services.xchange.constants.GenericGraphQLConstants.FILTER_VARIABLE_NAME;
import static com.opentext.solutions.services.xchange.constants.MembersGraphQLConstants.*;
import static com.opentext.solutions.services.xchangev2.constants.RoleConstants.SYSADMIN_EMAIL_ID;

@Service
public class MemberServiceConnector {

    @Autowired
    private AuthContextProvider authContextProvider;

    public static List<String> VALID_CONTRACT_ROLE_NAMES = Arrays.asList(V2_CONTRACT_COORDINATOR_ROLE_NAME,
            V2_CONTRACT_MEMBER_ROLE_NAME, V2_CONTRACT_DEFAULT_REVIEWER_ROLE_NAME);

    public static List<String> VALID_DELIVERABLE_LIST_ROLE_NAMES = Arrays.asList(V2_DELIVERABLE_LIST_DEFAULT_REVIEWER_ROLE_NAME,
            V2_DELIVERABLE_LIST_COORDINATOR_ROLE_NAME);

    @Autowired
    private GraphQLClientService graphQLClientService;

    public List<ParticipatingMember> getProjectMembers(String objectId, String roleName) {
        return graphQLClientService.triggerGraphQLQuery(
                MembersGraphQLConstants.GET_PROJECT_MEMBERS_QUERY,
                getVariables(objectId, roleName),
                MembersGraphQLConstants.GET_PROJECT_MEMBERS_QUERY_NAME,
                new TypeReference<List<ParticipatingMember>>() {
                },
                graphQLClientService.getServiceUrls().getProjectsApiUrl()
        ).stream().filter(m -> !(m.getEmail().equals(SYSADMIN_EMAIL_ID))).collect(Collectors.toList());
    }

    private String getVariables(String objectId, String roleName) {
        roleName = RoleNameUtils.getV3RoleName(roleName);
        FilterParticipantMemberInput.Builder filterParticipantMemberInputBuilder = FilterParticipantMemberInput.newBuilder();
        if (!StringUtils.isBlank(objectId)) {
            filterParticipantMemberInputBuilder.projectId(FilterIdInput.newBuilder().eq(objectId).build());
        }
        if (!StringUtils.isBlank(roleName)) {
            filterParticipantMemberInputBuilder.roleName(List.of(FilterStringInput.newBuilder().eq(roleName).build(), FilterStringInput.newBuilder().eq(ADMINISTRATOR_ROLE_NAME).build()));
        }
        filterParticipantMemberInputBuilder.fetchLastLoginInfo(Boolean.TRUE);
        return graphQLClientService.getVariablesString(Map.of(FILTER_VARIABLE_NAME, filterParticipantMemberInputBuilder.build()));
    }

    public List<ContractMember> getContractMembers(String objectId, String roleName) {
        String finalRoleName = RoleNameUtils.getV3RoleName(roleName);
        return graphQLClientService.triggerGraphQLQuery(
                MembersGraphQLConstants.GET_CONTRACT_MEMBERS_QUERY,
                getContractVariables(objectId),
                MembersGraphQLConstants.GET_CONTRACT_MEMBERS_QUERY_NAME,
                new TypeReference<List<ContractMember>>() {
                },
                graphQLClientService.getServiceUrls().getProjectsApiUrl()
        ).stream().filter(m -> !(m.getUserEmail().equals(SYSADMIN_EMAIL_ID)) && m.getRoleName().contains(finalRoleName)).collect(Collectors.toList());
    }

    private String getContractVariables(String objectId) {
        FilterContractMemberInput.Builder filterContractMemberInputBuilder = FilterContractMemberInput.newBuilder();
        if (!StringUtils.isBlank(objectId)) {
            filterContractMemberInputBuilder.contractId(FilterIdInput.newBuilder().eq(objectId).build());
        }
        filterContractMemberInputBuilder.fetchLastLoginInfo(Boolean.TRUE);
        return graphQLClientService.getVariablesString(Map.of(FILTER_VARIABLE_NAME, filterContractMemberInputBuilder.build()));
    }

    public List<Member> getDeliverableMembers(String objectId, String roleName) {
        return graphQLClientService.triggerGraphQLQuery(
                MembersGraphQLConstants.GET_DELIVERABLES_MEMBERS_QUERY,
                getDeliverableVariables(objectId, roleName),
                MembersGraphQLConstants.GET_DELIVERABLES_MEMBERS_QUERY_NAME,
                new TypeReference<List<Member>>() {
                },
                graphQLClientService.getServiceUrls().getAreasApiUrl()
        ).stream().filter(m -> !(m.getEmail().equals(SYSADMIN_EMAIL_ID))).collect(Collectors.toList());
    }

    private String getDeliverableVariables(String objectId, String roleName) {
        roleName = RoleNameUtils.getV3RoleName(roleName).toLowerCase();
        FilterMembersInput.Builder filterMembersInputBuilder = FilterMembersInput.newBuilder();
        if (!StringUtils.isBlank(objectId)) {
            filterMembersInputBuilder.objectId(objectId);
        }
        if (!StringUtils.isBlank(roleName)) {
            filterMembersInputBuilder.roleName(roleName);
        }
        filterMembersInputBuilder.fetchLastLoginInfo(Boolean.TRUE);
        return graphQLClientService.getVariablesString(Map.of(FILTER_VARIABLE_NAME, filterMembersInputBuilder.build()));
    }

    public List<Member> getDeliverableListMembers(String objectId, String roleName) {
        return graphQLClientService.triggerGraphQLQuery(
                MembersGraphQLConstants.GET_DELIVERABLE_LIST_MEMBERS_QUERY,
                getDeliverableVariables(objectId, roleName),
                MembersGraphQLConstants.GET_DELIVERABLE_LIST_MEMBERS_QUERY_NAME,
                new TypeReference<>() {
                },
                graphQLClientService.getServiceUrls().getAreasApiUrl()
        );
    }

    public ContractMember addContractMember(AddContractMemberDto roleMemberDto) {

        return graphQLClientService.getObjectFromSagaResponse(
                GraphQLUtil.triggerSyncSaga(MembersGraphQLConstants.CREATE_CONTRACT_MEMBER_SAGA,roleMemberDto,graphQLClientService, authContextProvider),
                MembersGraphQLConstants.CREATE_MEMBER_SAGA_RESP_KEY,
                new TypeReference<List<ContractMember>>() {
                }
        ).get(0);
    }

    public ParticipatingMember addProjectMember(AddProjectMemberDto roleMemberDto) {

        return graphQLClientService.getObjectFromSagaResponse(
                GraphQLUtil.triggerSyncSaga(MembersGraphQLConstants.CREATE_PROJECT_MEMBER_SAGA,roleMemberDto,graphQLClientService, authContextProvider),
                MembersGraphQLConstants.CREATE_PROJECT_MEMBER_SAGA_RESP_KEY,
                new TypeReference<List<ParticipatingMember>>() {
                }
        ).get(0);

    }

    public void validateProjectCoordinatorAccess(String projectId) throws ForbiddenException {
        boolean isProjectCoordinator = getProjectMembers(projectId, MembersGraphQLConstants.V2_PROJECT_COORDINATOR_ROLE_NAME)
                .stream()
                .anyMatch(member -> member.getEmail().equalsIgnoreCase(authContextProvider.getUserEmail()));
        if (!(authContextProvider.isApplicationAdmin() || authContextProvider.isServiceAccount() || authContextProvider.isTenantAdmin() || isProjectCoordinator)) {
            throw new ForbiddenException(ErrorCode.Forbidden, ErrorMessages.INSUFFICIENT_PERMISSIONS_TO_ACCESS_PROJECT_COORDINATORS);
        }
    }

    public void validateContractCoordinatorAccess(String contractId) throws ForbiddenException {
        boolean isContractCoordinator = getContractMembers(contractId, V2_CONTRACT_COORDINATOR_ROLE_NAME)
                .stream()
                .anyMatch(member -> member.getUserEmail().equalsIgnoreCase(authContextProvider.getUserEmail()));
        if (!(authContextProvider.isApplicationAdmin() || authContextProvider.isServiceAccount() || authContextProvider.isTenantAdmin() || isContractCoordinator)) {
            throw new ForbiddenException(ErrorCode.Forbidden, ErrorMessages.INSUFFICIENT_PERMISSIONS_TO_MANAGE_CUSTOM_PROPERTIES);
        }
    }

    public static void checkRoleNameForProject(String roleName) throws IllegalArgumentException {
        if (!V2_PROJECT_COORDINATOR_ROLE_NAME.equals(roleName)) {
            throw new IllegalArgumentException("Invalid role " + roleName + " for project");
        }
    }

    public static void checkRoleNameForContract(String roleName) throws IllegalArgumentException {
        if (!VALID_CONTRACT_ROLE_NAMES.contains(roleName)) {
            throw new IllegalArgumentException("Invalid role " + roleName + " for contract");
        }
    }

    public static void checkIdForContract(String id) throws IllegalArgumentException {
        final Pattern UUID_REGEX_PATTERN = Pattern.compile("^[{]?[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}[}]?$");
        Boolean valid = UUID_REGEX_PATTERN.matcher(id).matches();
        if (!valid) {
            throw new IllegalArgumentException("Contract_id "+ id +" is not a valid id");
        }
    }

    public static void checkRoleNameForDeliverableList(String roleName) throws IllegalArgumentException {
        if (!VALID_DELIVERABLE_LIST_ROLE_NAMES.contains(roleName)) {
            throw new IllegalArgumentException("Invalid role " + roleName + " for deliverable");
        }
    }
    public static void checkRoleNameForDeliverable(String roleName) throws IllegalArgumentException {
        if (!V2_DELIVERABLE_REVIEWER_ROLE_NAME.equals(roleName)) {
            throw new IllegalArgumentException("Invalid role " + roleName + " for deliverable");
        }
    }

    public Member addDeliverableListMember(AddDeliverableListMemberDto roleMemberDto) {
        return graphQLClientService.getObjectFromSagaResponse(
                GraphQLUtil.triggerSyncSaga(MembersGraphQLConstants.CREATE_DELIVERABLE_LIST_MEMBER_SAGA,roleMemberDto,graphQLClientService, authContextProvider),
                MembersGraphQLConstants.CREATE_DELIVERABLE_LIST_MEMBER_SAGA_RESP_KEY,
                new TypeReference<List<Member>>() {
                }
        ).get(0);

    }

    public Member addDeliverableMember(AddDeliverableMemberDto roleMemberDto) {

        return graphQLClientService.getObjectFromSagaResponse(
                GraphQLUtil.triggerSyncSaga(MembersGraphQLConstants.CREATE_DELIVERABLE_MEMBER_SAGA,roleMemberDto,graphQLClientService, authContextProvider),
                MembersGraphQLConstants.CREATE_DELIVERABLE_MEMBER_SAGA_RESP_KEY,
                new TypeReference<List<Member>>() {
                }
        ).get(0);

    }

    public ProjectMembershipCheck getProjectMemberStatus(String projectId, String userId) {
        Map<String, Object> variables = Map.of(
                "projectId", projectId,
                "userId", userId
        );
        List<ProjectMembershipCheck> response = graphQLClientService.triggerGraphQLQuery(
                MembersGraphQLConstants.PROJECT_MEMBER_STATUS_QUERY,
                graphQLClientService.getVariablesString(variables),
                MembersGraphQLConstants.PROJECT_MEMBER_STATUS_QUERY_NAME,
                new TypeReference<List<ProjectMembershipCheck>>() {
                },
                graphQLClientService.getServiceUrls().getProjectsApiUrl()
        );
        return response != null && !response.isEmpty() ? response.get(0) : null;
    }


}
