import com.opentext.solutions.common.auth.exception.ErrorMessage;
import com.opentext.solutions.services.generated.graphql.types.Contract;
import com.opentext.solutions.services.generated.graphql.types.Deliverable;
import com.opentext.solutions.services.generated.graphql.types.DeliverableList;
import com.opentext.solutions.services.generated.graphql.types.Project;
import com.opentext.solutions.services.xchange.model.AddContractMemberDto;
import com.opentext.solutions.services.xchange.model.AddDeliverableListMemberDto;
import com.opentext.solutions.services.xchange.model.AddDeliverableMemberDto;
import com.opentext.solutions.services.xchange.model.AddProjectMemberDto;
import com.opentext.solutions.services.xchange.model.ProjectMembershipCheck;
import com.opentext.solutions.services.xchange.service.*;
import com.opentext.solutions.services.xchangev2.exceptionhandler.ForbiddenException;
import com.opentext.solutions.services.xchangev2.constants.PageConstants;
import com.opentext.solutions.services.xchangev2.constants.RequestParamNames;
import com.opentext.solutions.services.xchangev2.constants.UrlMappings;
import com.opentext.solutions.services.xchangev2.response.model.EntryContent;
import com.opentext.solutions.services.xchangev2.response.model.EntryFeed;
import com.opentext.solutions.services.xchangev2.rolemembers.model.MemberV2;
import com.opentext.solutions.services.xchangev2.rolemembers.transformers.MembersTransformer;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;

import static com.opentext.solutions.services.xchangev2.constants.V2TypeNames.*;

@Controller
@RequiredArgsConstructor
@ApiResponses({
        @ApiResponse(responseCode = "401", description = "Unauthorized user access", content = @Content(schema = @Schema(hidden = true))) //
})
public class RoleMemberController {

    private final MemberServiceConnector memberServiceConnector;
    private final MembersTransformer membersTransformer;
    @Autowired
    private ContractServiceConnector contractServiceConnector;
    @Autowired
    private ProjectServiceConnector projectServiceConnector;
    @Autowired
    private DeliverableListServiceConnector deliverableListServiceConnector;
    @Autowired
    private DeliverableServiceConnector deliverableServiceConnector;

    @Operation(summary = "This API retrieves the users/members exists for a caseType(project | contract | deliverable | deliverableList) and case id provided under a subscription.")
    @ApiResponses(value = { @ApiResponse(responseCode = "200", description = "OK"),
            @ApiResponse(responseCode = "400", description = "Bad Request"),
            @ApiResponse(responseCode = "403", description = "Forbidden"),
            @ApiResponse(responseCode = "404", description = "Not found")
    })
    @GetMapping(value = UrlMappings.ROLE_MEMBERS, produces = {MediaType.APPLICATION_JSON_VALUE})
    @ResponseBody
    public EntryFeed getMembers(@PathVariable String caseType, @PathVariable String id, @PathVariable String roleName, @RequestParam(value = RequestParamNames.PAGE, defaultValue = PageConstants.DEFAULT_PAGE) Integer page,
                                @RequestParam(value = RequestParamNames.ITEMS_PER_PAGE, defaultValue = PageConstants.DEFAULT_ITEMS_PER_PAGE) Integer itemsPerPage) throws IllegalArgumentException, ForbiddenException {
        EntryFeed entryFeed;
        switch(caseType) {
            case V2_CASETYPE_PROJECT:
                memberServiceConnector.checkRoleNameForProject(roleName);
                id = projectServiceConnector.validateAndGetProjectId(id);
                memberServiceConnector.validateProjectCoordinatorAccess(id);
                entryFeed = membersTransformer.getProjectMembers(memberServiceConnector.getProjectMembers(id, roleName), id, page, itemsPerPage, roleName);
                break;
            case V2_CASETYPE_CONTRACT:
                memberServiceConnector.checkRoleNameForContract(roleName);
                id = contractServiceConnector.validateAndGetContractId(id);
                entryFeed = membersTransformer.getContractMembers(memberServiceConnector.getContractMembers(id, roleName), id, page, itemsPerPage, roleName);
                break;
            case V2_CASETYPE_DELIVERABLE:
                memberServiceConnector.checkRoleNameForDeliverable(roleName);
                Deliverable deliverable = deliverableServiceConnector.validateAndGetDeliverable(id);
                if(deliverable == null) {
                   throw new IllegalStateException("Deliverable Not Found");
                }
                entryFeed = membersTransformer.getMembers(memberServiceConnector.getDeliverableMembers(deliverable.getId(), roleName), deliverable.getId(), page, itemsPerPage, roleName);
                break;
            case V2_CASETYPE_DELIVERABLE_LIST:
                memberServiceConnector.checkRoleNameForDeliverableList(roleName);
                DeliverableList deliverableList = deliverableListServiceConnector.validateAndGetDeliverableList(id);
                if(deliverableList == null) {
                    throw new IllegalStateException("Deliverable List Not Found");
                }
                entryFeed = membersTransformer.getDeliverableListMembers(memberServiceConnector.getDeliverableListMembers(deliverableList.getId(), roleName), deliverableList.getId(), page, itemsPerPage, roleName);
                break;
            default:
                throw new IllegalStateException("Unsupported case type: " + caseType);
        }
       return entryFeed;
    }

    @Operation(summary = "This API creates the users/members based on the caseType(project | contract | deliverable | deliverableList) and case id provided under a subscription.")
    @ApiResponses(value = { @ApiResponse(responseCode = "201", description = "Created"),
            @ApiResponse(responseCode = "400", description = "Bad Request"),
            @ApiResponse(responseCode = "404", description = "Not found"),
            @ApiResponse(responseCode = "409", description = "Conflict", content = @Content(schema = @Schema(implementation = ErrorMessage.class)))
    })
    @PostMapping(value = UrlMappings.ROLE_MEMBERS, produces = {MediaType.APPLICATION_JSON_VALUE})
    @ResponseBody
    @ResponseStatus(HttpStatus.CREATED)
    public EntryContent createMembers(@PathVariable String caseType, @PathVariable String id, @PathVariable String roleName,
                                      @Valid  @RequestBody MemberV2 memberV2) {
        EntryContent entryContent;
        switch (caseType) {
            case V2_CASETYPE_CONTRACT:
                memberServiceConnector.checkRoleNameForContract(roleName);
                Contract contract = contractServiceConnector.getContract(contractServiceConnector.validateAndGetContractId(id), false);
                AddContractMemberDto contractRoleMemberDto = membersTransformer.sagaRequestBodyForAddContractMember(roleName, contract, memberV2.getEmail());
                entryContent = membersTransformer.getContractMemberV2(memberServiceConnector.addContractMember(contractRoleMemberDto));
            break;
            case V2_CASETYPE_PROJECT:
                memberServiceConnector.checkRoleNameForProject(roleName);
                Project project = projectServiceConnector.getProject(projectServiceConnector.validateAndGetProjectId(id), false);
                AddProjectMemberDto projectRoleMemberDto = membersTransformer.sagaRequestBodyForAddProjectMember(roleName, project.getId(), memberV2.getEmail());
                entryContent = membersTransformer.getProjectMemberV2(memberServiceConnector.addProjectMember(projectRoleMemberDto));
            break;
            case V2_CASETYPE_DELIVERABLE_LIST:
                memberServiceConnector.checkRoleNameForDeliverableList(roleName);
                DeliverableList deliverableList = deliverableListServiceConnector.validateAndGetDeliverableList(id);
                AddDeliverableListMemberDto roleMemberDto = membersTransformer.sagaRequestBodyForAddDeliverableListMember(roleName,
                        deliverableList.getId(), memberV2.getEmail());
                entryContent = membersTransformer.getDeliverableListMemberV2(memberServiceConnector.addDeliverableListMember(roleMemberDto));
            break;
            case V2_CASETYPE_DELIVERABLE:
                memberServiceConnector.checkRoleNameForDeliverable(roleName);
                Deliverable deliverable = deliverableServiceConnector.validateAndGetDeliverable(id);
                AddDeliverableMemberDto deliverableRoleMemberDto = membersTransformer.sagaRequestBodyForAddDeliverableMember(roleName,
                        deliverable.getId(), memberV2.getEmail());
                entryContent = membersTransformer.getDeliverableMemberV2(memberServiceConnector.addDeliverableMember(deliverableRoleMemberDto));
            break;
            default:
                throw new IllegalStateException("Unsupported case type: " + caseType);
        }
        return entryContent;
    }

    @Operation(summary = "This API checks if a user is already a member of the project.")
    @ApiResponses(value = { @ApiResponse(responseCode = "200", description = "OK"),
            @ApiResponse(responseCode = "400", description = "Bad Request"),
            @ApiResponse(responseCode = "403", description = "Forbidden"),
            @ApiResponse(responseCode = "404", description = "Not found")
    })
    @GetMapping(value = "/v2/projects/{projectId}/member-status", produces = {MediaType.APPLICATION_JSON_VALUE})
    @ResponseBody
    public ProjectMembershipCheck getProjectMemberStatus(@PathVariable String projectId, @RequestParam String userId) {
        return memberServiceConnector.getProjectMemberStatus(projectId, userId);
    }
}
