  onUserItemsAdd(users: ItemSelectItem[]) {
    const user = users[0];
    if (!user) {
      return;
    }

    const isDuplicate = this.displayedMembers.some(
      (dm) => dm.email.toLowerCase() === user.subLabel.toLowerCase()
    );

    if (isDuplicate) {
      this.notifService.showNotification('error', this.translateService.instant('MEMBER_EXISTS_IN_LIST'));
      this.removeUserItem.next(user);
      return;
    }

    this.checkProjectMembership(user);
  }

  private checkProjectMembership(user: ItemSelectItem) {
    const newMember: any = {
      key: user.key,
      name: user.label,
      email: user.subLabel,
      role: this.rolesData[0],
      organization: '',
      isNew: user.isNotInList,
      isExistingProjectMember: false,
    };

    this.projectService.checkProjectMembership(this.currProject.id, user.key).subscribe((result: ProjectMembershipCheck) => {
      if (result.isProjectMember) {
        newMember.isExistingProjectMember = true;
        this.isExistingProjectMember = true;
        this.existingOrganizationName = result.organizationName;
        newMember.organization = result.organizationName;
      } else {
        this.isExistingProjectMember = false;
        newMember.isExistingProjectMember = false;
      }
      this.displayedMembers.push(newMember);
      this.member.selectedUsers = [];
      if (this.userSelectComponent) {
        this.userSelectComponent.clear();
      }
    });
  }

